    // 1. Find the longest postfix of 'string' that is a palindrome.
    let longest_palindrome_suffix_start_index = -1;
    for (let i = 0; i < string.length; i++) {
        let suffix = string.substring(i);
        let reversed_suffix = suffix.split('').reverse().join('');
        if (suffix === reversed_suffix) {
            // We found a palindrome suffix. We want the longest one,
            // which means the smallest starting index i.
            if (longest_palindrome_suffix_start_index === -1 || i < longest_palindrome_suffix_start_index) {
                longest_palindrome_suffix_start_index = i;
            }
        }
    }

    // If the entire string is a palindrome, the longest suffix is the string itself.
    if (longest_palindrome_suffix_start_index === 0) {
        return string;
    }

    // 2. Determine the prefix that needs to be reversed and appended.
    // The prefix that needs to be reversed is the part *before* the longest palindromic suffix.
    // This prefix is string[0] up to string[longest_palindrome_suffix_start_index - 1].
    let prefix_to_reverse = string.substring(0, longest_palindrome_suffix_start_index);

    // 3. Reverse this prefix and append it to the string.
    let reversed_prefix = prefix_to_reverse.split('').reverse().join('');
    return string + reversed_prefix;
}

