    // Total number of n-digit positive integers is 9 * 10^(n-1)
    // We are looking for numbers that start with 1 OR end with 1.
    // Let A be the set of numbers that start with 1.
    // Let B be the set of numbers that end with 1.
    // We want to find |A U B| = |A| + |B| - |A intersect B|.

    // 1. Count of numbers starting with 1 (|A|)
    // The first digit is fixed as 1. The remaining n-1 digits can be anything (0-9).
    // |A| = 1 * 10^(n-1)
    const count_A = Math.pow(10, n - 1);

    // 2. Count of numbers ending with 1 (|B|)
    // The last digit is fixed as 1. The first digit cannot be 0 (1-9).
    // The first digit has 9 choices. The remaining n-2 digits have 10 choices each.
    // |B| = 9 * 10^(n-2) * 1 (for the last digit)
    // Wait, this is wrong.
    // If the last digit is 1, the first digit can be 1-9 (9 choices).
    // The middle n-2 digits can be 0-9 (10^(n-2) choices).
    // |B| = 9 * 10^(n-2)
    if (n === 1) {
        // If n=1, the only number is 1. It starts and ends with 1.
        // |B| = 1 (since the only 1-digit number ending in 1 is 1 itself).
        // The formula 9 * 10^(1-2) = 9 * 0.1 = 0.9 is incorrect for n=1.
        // Let's handle n=1 separately.
        return 1;
    }
    // For n >= 2:
    // First digit: 9 choices (1-9)
    // Middle n-2 digits: 10^(n-2) choices
    // Last digit: 1 choice (1)
    const count_B = 9 * Math.pow(10, n - 2);

    // 3. Count of numbers starting AND ending with 1 (|A intersect B|)
    // First digit is 1. Last digit is 1. The middle n-2 digits can be anything (0-9).
    // |A intersect B| = 1 * 10^(n-2) * 1
    const count_A_intersect_B = Math.pow(10, n - 2);

    // 4. Apply Inclusion-Exclusion Principle
    // |A U B| = |A| + |B| - |A intersect B|
    const total_count = count_A + count_B - count_A_intersect_B;

    return total_count;
}

