    // We need to evaluate an expression like: operand[0] operator[0] operand[1] operator[1] operand[2] ...
    // This is a standard infix expression evaluation problem.
    // We can use the Shunting-Yard algorithm to convert to postfix (RPN) and then evaluate,
    // or we can use two stacks (one for values, one for operators) directly for infix evaluation.

    // Let's use the two-stack approach for direct infix evaluation.

    const values = []; // Stack for operands/values
    const ops = [];   // Stack for operators

    // Helper function to apply an operator
    const applyOp = () => {
        const op = ops.pop();
        const b = values.pop();
        const a = values.pop();
        switch (op) {
            case '+':
                values.push(a + b);
                break;
            case '-':
                values.push(a - b);
                break;
            case '*':
                values.push(a * b);
                break;
            case '/': // Assuming standard division for simplicity if not specified, but the prompt mentions floor division (//)
            case '//':
                // Since the prompt implies standard Python-like behavior for the operators, we use // for floor division.
                values.push(Math.floor(a / b));
                break;
            case '**':
                values.push(Math.pow(a, b));
                break;
            default:
                throw new Error(`Unknown operator: ${op}`);
        }
    };

    // Helper function to determine operator precedence
    // Higher number means higher precedence
    const precedence = (op) => {
        if (op === '+' || op === '-') return 1;
        if (op === '*' || op === '/') return 2;
        if (op === '**') return 3; // Exponentiation usually has the highest precedence
        return 0;
    };

    // Combine operands and operators into a single token stream
    const tokens = [];
    for (let i = 0; i < operand.length; i++) {
        tokens.push({ type: 'operand', value: operand[i] });
        if (i < operator.length) {
            tokens.push({ type: 'operator', value: operator[i] });
        }
    }

    // Infix evaluation loop
    for (const token of tokens) {
        if (token.type === 'operand') {
            values.push(token.value);
        } else { // token.type === 'operator'
            const op = token.value;

            // While the top of the operator stack has higher or equal precedence, apply it
            while (ops.length > 0 && precedence(ops[ops.length - 1]) >= precedence(op)) {
                applyOp();
            }
            // Push the current operator onto the operator stack
            ops.push(op);
        }
    }

    // After processing all tokens, apply any remaining operators
    while (ops.length > 0) {
        applyOp();
    }

    // The final result is the only element left in the values stack
    return values[0];
}

